query Overview($range: MetricsRange!, $hideAdmin: Boolean!) {
  operations {
    health {
      status
      description
      queueDepth
      inProgress
      failedLastHour
      deadLetters
      __typename
    }
    metrics {
      server {
        uptimeSeconds
        workingSetBytes
        gcHeapBytes
        __typename
      }
      serverCpuPercent
      dashboard(range: $range, hideAdminTrains: $hideAdmin) {
        kpis {
          executionsToday
          successRate
          currentlyRunning
          unresolvedDeadLetters
          __typename
        }
        executionsOverTime {
          timestamp
          completed
          failed
          cancelled
          __typename
        }
        topFailures {
          trainName
          count
          __typename
        }
        topAverageDurations {
          trainName
          averageMilliseconds
          __typename
        }
        throughputSeries {
          trainName
          buckets {
            timestamp
            count
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
